"""Full-frame input audit, not a trained-model result."""
from pathlib import Path
import json,shutil,html
from PIL import Image
W=Path(__file__).parent;O=W.parents[1]/'outputs/baseline_engineering_20261018'
def main():
 C=W/'intersection_collected';r=json.loads((C/'lidar_camera_intersection_input_receipt.json').read_text())
 frames=[];dest=O/'intersection_input_frames';dest.mkdir(exist_ok=True)
 for raw in range(89,138):
  fid=f'0008{raw:03d}';src=C/'intersection_input_review/frames'/(fid+'.jpg')
  with Image.open(src) as im:assert im.size==(1920,2560)
  shutil.copy2(src,dest/src.name);frames.append(dict(id=fid,src='intersection_input_frames/'+src.name))
 rows=''.join(f'<tr><td>a{a["R15_actor"]}</td><td>c{a["camera_actor_index"]}</td><td>{n:,}</td><td><code>{html.escape(a["raw_laser_track_id"])}</code></td></tr>' for a,n in zip(r['selected'],r['dynamic_real_seed_points']))
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>B：20身份完整49帧输入复核</title><style>body{background:#0b1520;color:#e6f1fa;font:16px/1.6 system-ui,Microsoft YaHei;margin:0}main{max-width:1500px;margin:auto;padding:20px}a{color:#8ad4ff}.controls{position:sticky;top:0;z-index:2;background:#142b3ef2;padding:14px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;border:1px solid #54718b;border-radius:8px}button,input{font:inherit}button{padding:7px 15px}input[type=range]{flex:1;min-width:240px}#frame{display:block;width:100%;height:auto;margin:16px 0}table{border-collapse:collapse;width:100%}td,th{border:1px solid #38566d;padding:8px;text-align:left}code{overflow-wrap:anywhere}.muted{color:#b2c7d9}</style><main><h1>LiDAR∩前视相机：20身份输入复核</h1><p><a href="index.html">实验状态与恢复记录</a> · 这是训练输入，非新30K重建结果。</p><p>每帧上方是完整原图，下方是完整身份掩码叠加。保留整个视野，不裁ROI。颜色仅用于区分身份。13条相机独有轨迹不纳入本轮编辑集合，完整RGB仍保留。</p><div class="controls"><button id="play">播放</button><button id="prev">上一帧</button><input id="timeline" type="range" min="0" max="48" step="1" value="39" aria-label="原始帧时间轴"><button id="next">下一帧</button><output id="label"></output></div><img id="frame" alt="上：完整原始观测；下：相同完整画面身份预测叠加"><p class="muted">49帧完整画面已检查，20身份的原生动态掩码与初始化清单已核对。相机矩形仅作为部分实例分割提示，未填成车身；先验来自原49帧真实LiDAR，未按GT框逐点裁造。稀疏远车的边界和几何仍存在不确定性，输入准入不代表质量通过。</p><h2>同一批身份与真实初始化</h2><table><tr><th>Actor</th><th>相机轨迹索引</th><th>筛选后真实点</th><th>原始LiDAR轨迹</th></tr>__ROWS__</table><p>全部纳入车辆删除后仍可能看到排除的相机独有车辆；未观测的道路不自动补全。</p><img src="direct_architecture.svg" style="width:100%;height:auto" alt="输入到两条实验和完整画面评估的数据流"><script>const FRAMES=__FRAMES__;let frame=39,timer=null;const slider=document.getElementById('timeline'),image=document.getElementById('frame'),label=document.getElementById('label'),play=document.getElementById('play');function show(n){frame=Math.max(0,Math.min(48,n));slider.value=frame;image.src=FRAMES[frame].src;label.textContent='raw'+Number(FRAMES[frame].id.slice(-3))+' · '+(frame+1)+'/49';}function pause(){if(timer){clearInterval(timer);timer=null;}play.textContent='播放';}slider.addEventListener('input',()=>{pause();show(Number(slider.value));});document.getElementById('prev').onclick=()=>{pause();show(frame-1);};document.getElementById('next').onclick=()=>{pause();show(frame+1);};play.onclick=()=>{if(timer){pause();return;}play.textContent='暂停';timer=setInterval(()=>show((frame+1)%49),100);};document.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){pause();show(frame-1);e.preventDefault();}if(e.key==='ArrowRight'){pause();show(frame+1);e.preventDefault();}});show(frame);</script></main></html>'''
 (O/'intersection_inputs.html').write_text(page.replace('__ROWS__',rows).replace('__FRAMES__',json.dumps(frames)),encoding='utf-8');print('full49 input page generated')
if __name__=='__main__':main()
